def compute_order_amount(on_hand_inventory, pipeline_orders):
    bs = 100.0  # OPT_PARAM: {"initial": 100.0, "min": 100.0, "max": 5000.0, "type": "float"}
    w_i = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 3.0, "type": "float"}
    w_pipe = 0.1  # OPT_PARAM: {"initial": 0.1, "min": 0.0, "max": 3.0, "type": "float"}
    discount = 1.2  # OPT_PARAM: {"initial": 1.2, "min": 0.8, "max": 1.2, "type": "float"}
    ip = w_i * on_hand_inventory
    w = w_pipe
    for q in pipeline_orders:
        ip += w * q
        w *= discount
    order_amount = max(0.0, bs - ip)
    return order_amount
